import { Injectable, signal } from '@angular/core';
import { HttpErrorResponse } from '@angular/common/http';

export type MessageStyle = 'SUCCESS' | 'ERROR';
export interface Message { id: number; text: string; style: MessageStyle; }

@Injectable({ providedIn: 'root' })
export class MessageService {
  readonly messages = signal<Message[]>([]);
  private nextId = 1;

  success(text: string): void { this.add(text, 'SUCCESS'); }
  error(err: unknown): void {
    let text = 'An unexpected error occurred.';
    if (err instanceof HttpErrorResponse) {
      const body = typeof err.error === 'string' ? err.error.trim() : '';
      text = body && !body.startsWith('<') && body.length < 300 ? body : `Request failed: ${err.status} ${err.statusText}`.trim();
    } else if (err instanceof Error) {
      text = err.message;
    }
    this.add(text, 'ERROR');
  }

  /** Messages close after MessageCloseDelay.DEFAULT (5s). */
  add(text: string, style: MessageStyle, closeDelay = 5000): void {
    const msg: Message = { id: this.nextId++, text, style };
    this.messages.update((l) => [...l, msg]);
    if (closeDelay > 0) setTimeout(() => this.close(msg), closeDelay);
  }

  close(msg: Message): void { this.messages.update((l) => l.filter((m) => m !== msg)); }
}
