@Component({
  selector: 'app-edit-rating',
  standalone: true,
  imports: [FormsModule],
  template: `
    @if (cars(); as list) {
      <div class="glass" (click)="closed.emit()"></div>
      <div class="popup">
        <div>
          <span>Car:</span>
          <select [(ngModel)]="car">
            @for (c of list; track $index) { <option [ngValue]="c">{{ carLabel(c) }}</option> }
          </select>
        </div>
        <div>
          <span>Your rating:</span>
          <input type="text" inputmode="numeric" maxlength="3" id="gwt-debug-ratingInput" [(ngModel)]="rating">
        </div>
        <div>
          <button type="button" id="gwt-debug-ratingSave" (click)="onSave()" [disabled]="saving">Save</button>
          <button type="button" (click)="closed.emit()">Close</button>
        </div>
      </div>
    }`,
})
export class EditRatingComponent implements OnInit {
  private api = inject(ApiService);
  private messages = inject(MessageService);

  @Output() saved = new EventEmitter<RatingDto>();
  @Output() closed = new EventEmitter<void>();

  readonly cars = signal<CarDto[] | null>(null);
  readonly carLabel = carLabel;
  car: CarDto | null = null;
  rating = '';
  saving = false;

  ngOnInit(): void {
    this.api.getAllCars().subscribe({
      next: (l) => { const cars = l ?? []; this.car = cars[0] ?? null; this.cars.set(cars); },
      error: (e) => { this.messages.error(e); this.closed.emit(); },
    });
  }

  onSave(): void {
    const text = String(this.rating ?? '').trim();
    const value = text === '' ? null : Number(text);
    if (value !== null && !Number.isInteger(value)) {
      this.messages.error(new Error(`"${text}" is not a valid number.`));
      return;
    }
    this.saving = true;
    this.api.saveRating({ rating: value, car: this.car }).subscribe({
      next: (r) => {
        this.saving = false;
        this.messages.success('The rating has been saved.');
        this.saved.emit(r);
      },
      error: (e) => { this.saving = false; this.messages.error(e); },
    });
  }
}
